-- Add the confirmed cathedral stop without changing existing labels.
alter table public.m3_photos drop constraint london_inspiration_valid;
alter table public.m3_photos add constraint london_inspiration_valid check (inspiration = '' or (vault = 'london-2028' and inspiration in ('packing-bags', 'most-excited', 'dreaming-of-london', 'airport-hellos', 'window-seat', 'st-pauls-cathedral', 'tower-of-london', 'fish-and-chips', 'london-dungeon', 'national-portrait-gallery', 'trafalgar-square', 'w-london', 'westminster-abbey', 'british-museum', 'madame-tussauds', 'six', 'hampton-court', 'stonehenge', 'wicked', 'train-to-paris', 'louvre', 'bistrot-de-la-montagne', 'eiffel-tower', 'paris-hotel', 'versailles', 'napoleons-tomb', 'notre-dame', 'seine-cruise', 'home-again', 'little-moments')));
